//! Schema parity gate: the sqlx migration run must produce exactly the
//! schema the production drizzle migrator produces from the same SQL files.
//!
//! The fixture (tests/fixtures/schema.json) is generated by
//! `bun rust/parity/schema-snapshot.ts`, which applies server/db/migrations
//! with `drizzle-orm/node-postgres/migrator` to a scratch database. This test
//! applies the same files through `MIGRATOR`, snapshots its scratch database
//! with the same queries, and diffs the two.
//!
//! Gated on TEST_DATABASE_URL — an admin connection string allowed to create
//! databases (its database name is ignored), e.g.
//! `postgres://bopixi:bopixi@127.0.0.1:55432/postgres`.

use std::collections::BTreeSet;
use std::str::FromStr;
use std::time::{SystemTime, UNIX_EPOCH};

use serde_json::{json, Value};
use sqlx::postgres::{PgConnectOptions, PgPool, PgPoolOptions};

use bopixi_db::MIGRATOR;

type ColumnRow = (
    String,
    i32,
    String,
    String,
    String,
    bool,
    Option<String>,
    bool,
    Option<String>,
);

#[tokio::test]
async fn sqlx_migrations_reproduce_the_drizzle_schema() {
    let Ok(admin_url) = std::env::var("TEST_DATABASE_URL") else {
        eprintln!("TEST_DATABASE_URL is unset; schema parity test skipped");
        return;
    };
    let admin_options =
        PgConnectOptions::from_str(&admin_url).expect("TEST_DATABASE_URL must be a connection URL");
    let admin = PgPoolOptions::new()
        .max_connections(1)
        .connect_with(admin_options.clone())
        .await
        .expect("connect to the maintenance database");

    let stamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("clock before the epoch")
        .as_nanos();
    let scratch = format!("bopixi_parity_{}_{stamp}", std::process::id());
    sqlx::query(&format!(r#"create database "{scratch}""#))
        .execute(&admin)
        .await
        .expect("create the scratch database");

    let pool = PgPoolOptions::new()
        .max_connections(4)
        .connect_with(admin_options.database(&scratch))
        .await
        .expect("connect to the scratch database");
    MIGRATOR.run(&pool).await.expect("run the migrations");
    let actual = snapshot(&pool).await;
    pool.close().await;

    sqlx::query(&format!(
        r#"drop database if exists "{scratch}" with (force)"#
    ))
    .execute(&admin)
    .await
    .expect("drop the scratch database");
    admin.close().await;

    let expected: Value =
        serde_json::from_str(include_str!("fixtures/schema.json")).expect("fixture is valid JSON");
    let mut problems = Vec::new();
    for section in ["tables", "columns", "constraints", "indexes", "enums"] {
        compare(section, &expected[section], &actual[section], &mut problems);
    }
    assert!(
        problems.is_empty(),
        "sqlx schema diverges from the drizzle fixture ({} differences):\n{}",
        problems.len(),
        problems
            .iter()
            .take(40)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

fn compare(section: &str, expected: &Value, actual: &Value, problems: &mut Vec<String>) {
    let entries = |value: &Value| -> BTreeSet<String> {
        value
            .as_array()
            .expect("snapshot section is an array")
            .iter()
            .map(ToString::to_string)
            .collect()
    };
    let expected = entries(expected);
    let actual = entries(actual);
    for missing in expected.difference(&actual) {
        problems.push(format!("{section}: missing  {missing}"));
    }
    for extra in actual.difference(&expected) {
        problems.push(format!("{section}: unexpected {extra}"));
    }
}

async fn snapshot(pool: &PgPool) -> Value {
    const NOT_JOURNALS: &str = "table_name not in ('_sqlx_migrations', '__drizzle_migrations')";

    let tables: Vec<(String,)> = sqlx::query_as(&format!(
        r#"select table_name::text from information_schema.tables
            where table_schema = 'public' and table_type = 'BASE TABLE' and {NOT_JOURNALS}
            order by table_name"#
    ))
    .fetch_all(pool)
    .await
    .expect("tables");

    let columns: Vec<ColumnRow> = sqlx::query_as(&format!(
        r#"select table_name::text, ordinal_position, column_name::text,
                      data_type::text, udt_name::text, is_nullable::text = 'YES',
                      column_default::text, is_identity::text = 'YES',
                      identity_generation::text
                 from information_schema.columns
                where table_schema = 'public' and {NOT_JOURNALS}
                order by table_name, ordinal_position"#
    ))
    .fetch_all(pool)
    .await
    .expect("columns");

    let constraints: Vec<(String, String, String, String)> = sqlx::query_as(
        r#"select cl.relname::text, c.conname::text, c.contype::text,
                  pg_get_constraintdef(c.oid)::text
             from pg_constraint c
             join pg_class cl on cl.oid = c.conrelid
             join pg_namespace n on n.oid = c.connamespace
            where n.nspname = 'public' and cl.relname <> '_sqlx_migrations'
            order by 1, 2"#,
    )
    .fetch_all(pool)
    .await
    .expect("constraints");

    let indexes: Vec<(String, String, String)> = sqlx::query_as(
        r#"select tablename::text, indexname::text, indexdef::text
             from pg_indexes
            where schemaname = 'public'
              and tablename not in ('_sqlx_migrations', '__drizzle_migrations')
            order by tablename, indexname"#,
    )
    .fetch_all(pool)
    .await
    .expect("indexes");

    let enum_rows: Vec<(String, String)> = sqlx::query_as(
        r#"select t.typname::text, e.enumlabel::text
             from pg_type t
             join pg_enum e on e.enumtypid = t.oid
             join pg_namespace n on n.oid = t.typnamespace
            where n.nspname = 'public'
            order by t.typname, e.enumsortorder"#,
    )
    .fetch_all(pool)
    .await
    .expect("enums");
    let mut enums: Vec<Value> = Vec::new();
    for (name, label) in enum_rows {
        match enums.last_mut() {
            Some(last) if last["type"] == json!(name) => last["labels"]
                .as_array_mut()
                .expect("labels")
                .push(json!(label)),
            _ => enums.push(json!({ "type": name, "labels": [label] })),
        }
    }

    json!({
        "tables": tables.into_iter().map(|(name,)| name).collect::<Vec<_>>(),
        "columns": columns.into_iter().map(|(table, position, name, data_type, udt, nullable, default, identity, generation)| json!({
            "table": table,
            "position": position,
            "name": name,
            "type": data_type,
            "udt": udt,
            "nullable": nullable,
            "default": default,
            "identity": identity,
            "identityGeneration": generation,
        })).collect::<Vec<_>>(),
        "constraints": constraints.into_iter().map(|(table, name, kind, definition)| json!({
            "table": table,
            "name": name,
            "type": kind,
            "definition": definition,
        })).collect::<Vec<_>>(),
        "indexes": indexes.into_iter().map(|(table, name, definition)| json!({
            "table": table,
            "name": name,
            "definition": definition,
        })).collect::<Vec<_>>(),
        "enums": enums,
    })
}
